use std::fmt::Write as _;
use std::process::ExitCode;

use wgpu::util::DeviceExt;

const SHADER: &str = r#"
struct Dims { width: u32, height: u32 }

@group(0) @binding(0) var<uniform> dims: Dims;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

@compute @workgroup_size(16, 16)
fn step(@builtin(global_invocation_id) id: vec3<u32>) {
    if (id.x >= dims.width || id.y >= dims.height) {
        return;
    }
    var n: u32 = 0u;
    for (var dy: i32 = -1; dy <= 1; dy = dy + 1) {
        for (var dx: i32 = -1; dx <= 1; dx = dx + 1) {
            if (dx == 0 && dy == 0) {
                continue;
            }
            let x = i32(id.x) + dx;
            let y = i32(id.y) + dy;
            if (x < 0 || y < 0 || x >= i32(dims.width) || y >= i32(dims.height)) {
                continue;
            }
            n = n + src[u32(y) * dims.width + u32(x)];
        }
    }
    let i = id.y * dims.width + id.x;
    let alive = src[i] == 1u;
    dst[i] = select(u32(n == 3u), u32(n == 2u || n == 3u), alive);
}
"#;

struct Input {
    width: usize,
    height: usize,
    generations: usize,
    cells: Vec<u32>,
}

fn parse(text: &str) -> Result<Input, String> {
    let mut rest = text;
    let mut header = [0usize; 3];
    for slot in &mut header {
        rest = rest.trim_start();
        let end = rest.find(char::is_whitespace).unwrap_or(rest.len());
        *slot = rest[..end]
            .parse()
            .map_err(|_| "bad header".to_string())?;
        rest = &rest[end..];
    }
    let [width, height, generations] = header;
    if width == 0 || height == 0 {
        return Err("empty grid".into());
    }
    let cells: Vec<u32> = rest
        .chars()
        .filter(|c| *c == '0' || *c == '1')
        .map(|c| u32::from(c == '1'))
        .collect();
    if cells.len() != width * height {
        return Err(format!(
            "expected {} cells, found {}",
            width * height,
            cells.len()
        ));
    }
    Ok(Input {
        width,
        height,
        generations,
        cells,
    })
}

fn run_gpu(input: &Input) -> Result<Vec<u32>, String> {
    let instance = wgpu::Instance::new(wgpu::InstanceDescriptor::default());
    let adapter = pollster::block_on(instance.request_adapter(&wgpu::RequestAdapterOptions::default()))
        .map_err(|e| format!("no GPU adapter: {e}"))?;
    let (device, queue) =
        pollster::block_on(adapter.request_device(&wgpu::DeviceDescriptor::default()))
            .map_err(|e| format!("no device: {e}"))?;

    let size = (input.cells.len() * 4) as u64;
    let dims = [input.width as u32, input.height as u32];
    let dims_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: None,
        contents: bytemuck::cast_slice(&dims),
        usage: wgpu::BufferUsages::UNIFORM,
    });
    let make = |data: &[u32]| {
        device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
            label: None,
            contents: bytemuck::cast_slice(data),
            usage: wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC,
        })
    };
    let bufs = [make(&input.cells), make(&vec![0u32; input.cells.len()])];
    let staging = device.create_buffer(&wgpu::BufferDescriptor {
        label: None,
        size,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });

    let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: None,
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });
    let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
        label: None,
        layout: None,
        module: &module,
        entry_point: Some("step"),
        compilation_options: Default::default(),
        cache: None,
    });
    let layout = pipeline.get_bind_group_layout(0);
    let groups: Vec<wgpu::BindGroup> = (0..2)
        .map(|i| {
            device.create_bind_group(&wgpu::BindGroupDescriptor {
                label: None,
                layout: &layout,
                entries: &[
                    wgpu::BindGroupEntry {
                        binding: 0,
                        resource: dims_buf.as_entire_binding(),
                    },
                    wgpu::BindGroupEntry {
                        binding: 1,
                        resource: bufs[i].as_entire_binding(),
                    },
                    wgpu::BindGroupEntry {
                        binding: 2,
                        resource: bufs[1 - i].as_entire_binding(),
                    },
                ],
            })
        })
        .collect();

    let gx = input.width.div_ceil(16) as u32;
    let gy = input.height.div_ceil(16) as u32;
    let mut done = 0;
    while done < input.generations {
        let batch = (input.generations - done).min(50);
        let mut encoder = device.create_command_encoder(&Default::default());
        for g in done..done + batch {
            let mut pass = encoder.begin_compute_pass(&Default::default());
            pass.set_pipeline(&pipeline);
            pass.set_bind_group(0, &groups[g % 2], &[]);
            pass.dispatch_workgroups(gx, gy, 1);
        }
        queue.submit([encoder.finish()]);
        done += batch;
    }

    let mut encoder = device.create_command_encoder(&Default::default());
    encoder.copy_buffer_to_buffer(&bufs[input.generations % 2], 0, &staging, 0, size);
    queue.submit([encoder.finish()]);

    let slice = staging.slice(..);
    let (tx, rx) = std::sync::mpsc::channel();
    slice.map_async(wgpu::MapMode::Read, move |r| {
        let _ = tx.send(r);
    });
    device
        .poll(wgpu::PollType::wait_indefinitely())
        .map_err(|e| format!("poll failed: {e}"))?;
    rx.recv()
        .map_err(|e| e.to_string())?
        .map_err(|e| format!("map failed: {e}"))?;
    let data = slice.get_mapped_range();
    let out: Vec<u32> = bytemuck::cast_slice(&data).to_vec();
    drop(data);
    staging.unmap();
    Ok(out)
}

fn run() -> Result<String, String> {
    let path = std::env::args().nth(1).ok_or("usage: life <input file>")?;
    let text = std::fs::read_to_string(&path).map_err(|e| format!("{path}: {e}"))?;
    let input = parse(&text)?;
    let cells = run_gpu(&input)?;

    let mut out = String::new();
    for row in cells.chunks(input.width) {
        let line: Vec<&str> = row.iter().map(|&c| if c != 0 { "1" } else { "0" }).collect();
        out.push_str(&line.join(" "));
        out.push('\n');
    }
    let alive = cells.iter().filter(|&&c| c != 0).count();
    let _ = writeln!(out, "ALIVE {alive}");
    Ok(out)
}

fn main() -> ExitCode {
    match run() {
        Ok(out) => {
            print!("{out}");
            ExitCode::SUCCESS
        }
        Err(e) => {
            eprintln!("error: {e}");
            ExitCode::FAILURE
        }
    }
}
